 "home_svc_eyebrow": "03 / Tjenester",
 "home_svc_h2": "Vi styrer metallbearbeidingen <span style=\"color:var(--arc-2)\">med ingeniørdisiplin</span> fra start til slutt.",
 "home_svc_lede": "Sveiseteknikk og NDT i eget hus; kutting, bøying og mekanisk montering planlagt inn i prosjektflyten. Ett kontaktpunkt, ingeniørstyrt prosess.",
 "home_svc_cta": "Se alle tjenester",
 "home_trace_eyebrow": "04 / Sporbarhetsprosess",
 "home_trace_h2": "Fra råmateriale til levering;<br/>7 trinn,<br/><span class=\"arc\">ingen blindsoner.</span>",
 "home_trace_lede": "Hos ArmaWeld åpnes hver arbeidsordre med et digitalt serienummer; smeltenummer, WPS, sveiser, NDT-rapport, dimensjonskontroll og fraktdokument samles i samme registrering. Hold musepekeren over trinnene nedenfor for å se nærmere på et hvilket som helst punkt i produksjonsløpet.",
 "home_trace_meta_heat": "Smeltenummer",
 "home_trace_meta_wps": "WPS",
 "home_trace_meta_op": "Operatør",
 "home_trace_meta_date": "Dato",
 "home_cmp_eyebrow": "05 / Sammenligning av sveiseprosesser",
 "home_cmp_h2": "Hvilken lysbue til <span style=\"color:var(--arc-2)\">hvilken jobb?</span> Tekniske fakta i et overblikk.",
 "home_ref_eyebrow": "Referanser",
 "home_ref_h2": "Fra sveiset fabrikasjon til NDT-rapporter, <span style=\"color:var(--arc-2)\">én ubrutt ansvarskjede.</span>",
 "home_cta_eyebrow": "La oss samarbeide",
 "home_cta_h2": "Send tegningene deres — <span class=\"arc\">tilbud innen 48 timer.</span>",
 "home_cta_lede": "Vi går gjennom DWG/DXF/PDF-filene deres og gir et komplett pristilbud som inkluderer sveisemetode, materialkvalitet, gjeldende WPS og NDT-plan.",
