 "home_cnt1_lbl": "Sveisesøm / 2026 Q1",
 "home_cnt1_sub": "Sanntidsdata fra verkstedet · MIG+TIG+E-ARC totalt",
 "home_cnt2_lbl": "Sporbarhetsgrad",
 "home_cnt2_sub": "Hver del registrert med serienummer",
 "home_cnt3_lbl": "NDT-avvisningsrate",
 "home_cnt3_sub": "≈65 % under bransjegjennomsnittet",
