 "about_breadcrumb": "Om oss",
 "about_h1": "Grundig ingeniørdisiplin.<br/><span class=\"arc\">En produksjonsfilosofi formet av erfaring.</span>",
 "about_lede": "ArmaWeld driver sveiset fabrikasjon og NDT ved produksjonsanlegget vårt i Konya; kutting, bøying og montering koordineres innenfor prosjektplanen. Teamet vårt anvender sveiseteknisk erfaring fra OEM-er og prosessanlegg med fokus på prosess, dokumentasjon og sporbarhet.",
 "about_mani_quote": "Vi leverer ikke bare produktet, men sporbar kvalitetsdokumentasjon.",
 "about_team_eyebrow": "01 / Ingeniørteam",
 "about_team_h2": "Ekspertteamet som <span style=\"color:var(--arc-2)\">driver produksjonen.</span>",
 "about_team_lede": "Bak ArmaWeld står et team av maskiningeniører som behersker kvalitetsledelse og produksjonsprosesser, internasjonalt kvalifiserte sveiseingeniører og NDT-spesialister sertifisert etter EN ISO 9712. Hver disiplin har fordypet seg i sitt eget felt; sammen dokumenterer de hver del fra råmateriale til leveringsrapport.",
 "about_disc1_n": "SVEISETEKNIKK",
 "about_disc1_h": "Internasjonalt sertifiserte<br/>sveiseingeniører.",
 "about_disc1_p": "IWE-/IWT-utdannede ingeniører styrer hvert trinn i kvalitetssystemet etter EN ISO 3834-2 — utvikling av WPS, godkjenning av WPQR og kvalifikasjonsmatriser for sveisere. Hver sveis bærer en ingeniørs signatur.",
 "about_disc2_n": "MASKINTEKNIKK",
 "about_disc2_h": "Maskiningeniører som behersker<br/>alt fra design til produksjon.",
 "about_disc2_p": "Maskiningeniørene våre, med mange års erfaring fra produksjonslinjer, har ansvar for mekanisk design, FEA og produksjonsplanlegging. De bygger ryggraden i produksjonen fra DWG til ferdig produkt.",
 "about_disc3_n": "NDT / INSPEKSJON",
 "about_disc3_h": "NDT-spesialister<br/>EN ISO 9712 nivå 2.",
 "about_disc3_p": "Vårt nivå 2-sertifiserte inspeksjonspersonell utarbeider inspeksjonsplanen og godkjenner rapportene for hver jobb. Akseptkriteriene baseres på EN ISO 5817 klasse B; ingen sveis forlater verkstedet uten registrering.",
 "about_stats_eyebrow": "02 / Tall",
 "about_stats_h2": "ArmaWeld i tall.",
 "about_val_eyebrow": "03 / Verdier",
 "about_val_h2": "De <span style=\"color:var(--arc-2)\">fire kjerneprinsippene</span> vi aldri går på akkord med.",
 "about_val1_h": "Sporbar produksjon er ikke til forhandling.",
 "about_val1_p": "Hver dels råmateriale, sveiser, WPS og NDT-registrering er koblet sammen. Vi produserer ikke deler uten serienummer.",
 "about_val2_h": "Ingeniørbeslutninger tas på verkstedgulvet.",
 "about_val2_p": "Hver arbeidsordre går gjennom ingeniørgodkjenning. Når det oppstår problemer, er det ingeniørene våre — som selv kan ta på sveisemasken og stille seg ved lysbuen — som tar beslutningen.",
 "about_val3_h": "En udokumentert sveis behandles som om den aldri ble utført.",
 "about_val3_p": "Usertifisert sveiser, ikke-godkjent WPS, urapportert NDT — uakseptabelt for oss. Papiret er like alvorlig som stålet.",
 "about_val4_h": "Feil skjules ikke — de registreres.",
 "about_val4_p": "Et avvik er ikke uansvarlighet — det er en læringsmulighet. Med CAPA-systemet vårt lukkes hvert avvik med rotårsaksanalyse.",
 "about_fac_eyebrow": "03 / Produksjonsanlegg og prosess",
 "about_fac_h2": "Planlagt verkstedlayout,<br/><span style=\"color: var(--arc-2);\">jevn produksjonskvalitet.</span>",
 "about_cta_h2": "La oss vurdere prosjektet deres sammen.",
 "about_cta_lede": "Send den tekniske tegningen; så fastsetter vi prosess, WPS og NDT-plan i fellesskap.",
 "about_cta_btn": "Tilbudsskjema →",
 "about_cta_eyebrow": "Neste steg",
 "services_breadcrumb": "Tjenester",
 "services_h1": "Sveiset fabrikasjon og<br/><span class=\"arc\">integrert prosjektledelse.</span>",
 "services_lede": "Sveiset fabrikasjon og NDT i eget hus; platekutting, bøying og mekanisk montering planlagt inn i prosjektflyten. Ett kontaktpunkt, ingeniørstyrt prosess og dokumentdisiplin.",
 "services_s01_num": "// 01 · SVEISET FABRIKASJON",
 "services_s01_h2": "Sveiset fabrikasjon og stålkonstruksjoner.",
 "services_s01_desc": "ArmaWelds opprinnelige formål. Vi arbeider med sertifiserte sveisere innen MIG/MAG, TIG og dekkede elektroder (MMA), kvalifiserte WPS og kvalitetsrammeverket i EN ISO 3834-2. Fra kranstrukturer til trykkbeholdere, fra gravemaskinskuffer til prosesstanker — hver geometri og hvert materiale er knyttet til en passende prosedyre.",
 "services_s02_num": "// 02 · PLATEKUTTING",
 "services_s02_h2": "Platekutting og toleransestyring.",
 "services_s02_desc": "En integrert kuttelinje fra deres DXF til ferdig del. CNC-plasma, laser og platesaks utføres i henhold til prosjektspesifikasjonen. Delene leveres med sveiseklar toleranse; fugeforberedelse definert i spesifikasjonen fullføres i samme flyt.",
 "services_s03_num": "// 03 · BØYING",
 "services_s03_h2": "Bøying og forming.",
 "services_s03_desc": "Plate- og profildeler bringes til målgeometri gjennom V-/U-bøying, sylindrisk forming og profilforming. Hver bøy planlegges med vinkelsimulering, beregning av nøytralakse og kompensasjon for tilbakefjæring. For deler med flere bøyer utarbeider ingeniørteamet en analyse av bøyetillegg.",
 "services_s04_num": "// 04 · MEKANISK MONTERING",
 "services_s04_h2": "Mekanisk montering og delsystemer.",
 "services_s04_desc": "Store konstruksjoner produseres som delmontasjer, deretter fikseres og sammenføyes de i verkstedet ved hjelp av mal- og jiggsystemer. For prosjekter med modulær forsendelse fullføres montasjen på stedet av et erfarent mobilt team.",
 "services_s05_num": "// 05 · NDT",
 "services_s05_h2": "NDT / Ikke-destruktiv testing.",
 "services_s05_desc": "Sveisekvalitet vurderes ikke bare ut fra overflatens utseende. Hos ArmaWeld inspiseres hver kritisk sveis utover visuell kontroll (VT): penetrant (PT) eller magnetpulver (MT) for overflatesprekker, ultralyd (UT) eller radiografi (RT) for indre feil.",
 "services_cta_h2": "Få et tilbud på prosjektet deres.",
 "services_cta_btn": "Tilbudsskjema →",
 "quality_breadcrumb": "Kvalitet",
 "quality_h1": "Kvalitet og<br/><span class=\"arc\">sporbarhet.</span>",
 "quality_lede": "Produksjonsprosesser revidert etter internasjonale standarder, sertifisert personell og et fullt sporbart registreringssystem.",
 "quality_certs_eyebrow": "01 / Sertifiseringer",
 "quality_certs_h2": "Aktive sertifiseringer og kvalifikasjoner.",
 "quality_process_eyebrow": "02 / Kvalitetsprosess",
 "quality_process_h2": "Kvalitetskontroll i 7 trinn.",
 "quality_kpi_eyebrow": "03 / KPI",
 "quality_kpi_h2": "Målte kvalitetsindikatorer.",
 "quality_cta_eyebrow": "Eksempel på dokumentpakke",
 "quality_cta_h2": "Se <span style=\"color:var(--arc-2)\">dokumentpakken</span> vi leverer.",
 "quality_cta_btn": "Åpne eksempelfil",
 "ndt_breadcrumb": "NDT",
 "ndt_h1": "NDT /<br/><span class=\"arc\">Ikke-destruktiv testing.</span>",
 "ndt_lede": "VT-, PT-, MT- og UT-inspeksjon i eget hus med personell sertifisert etter EN ISO 9712 nivå II. Lisensiert partner for RT.",
 "ndt_scope_eyebrow": "01 / Omfang",
 "ndt_scope_h2": "Inspeksjonsomfang internt og eksternt.",
