 "sectors_s01_num": "// 01 · MASKINER",
 "sectors_s01_h2": "Maskiner og<br/><span class=\"arc\">anleggsutstyr.</span>",
 "sectors_s01_desc": "Fabrikasjon av skuffer, chassis og maskinkropper i HARDOX, Strenx og høyfast stål. Spesialiserte WPS for slitasje- og høyfaste materialer.",
