 "sectors_s03_desc": "Trykkbeholdere og prosesstanker etter PED kat. I–II. Fullt gjennomsveisede forbindelser, 100 % NDT og CE-erklæring.",
 "sectors_s04_num": "// 04 · ENERGI",
