 "home_svc_r1_name": "Sveiset fabrikasjon",
 "home_svc_r1_brief": "Fra S235 til Strenx 1100, S690QL og S960QL til HARDOX — pålitelig produksjon i alle stålgrupper, inkludert rustfritt og aluminium, med godkjente WPS.",
 "home_svc_r2_name": "Platekutting og profilbearbeiding",
 "home_svc_r2_brief": "Karbonstål, rustfritt, Hardox, Strenx og aluminium — toleransestyrt kutting og sveiseklar forberedelse etter teknisk tegning.",
 "home_svc_r3_name": "Bøying og forming",
 "home_svc_r3_brief": "V-bøying, U-forming og sylindrisk forming — programmert styring av vinkel, radius og monteringspasning.",
 "home_svc_r4_name": "Mekanisk montering og forsendelsesklargjøring",
 "home_svc_r4_brief": "Delmontering, momentregistrering og funksjonstesting — forsendelsesemballering integrert i prosjektplanen.",
 "home_svc_r5_name": "NDT og ikke-destruktiv testing",
 "home_svc_r5_brief": "4 inspeksjonsmetoder i eget hus, akseptkriterier etter EN ISO 5817 klasse B — hver sveis dokumentert, ingen registrering utelatt.",
 "home_svc_r6_name": "Maskinkropper og skuffer til anleggsmaskiner",
 "home_svc_r6_brief": "Fabrikasjon av skuffer, skåler, blad og maskinkropper i slitestål — seriejigger og MT-inspeksjon inkludert.",
 "home_svc_r7_name": "Krankonstruksjon",
 "home_svc_r7_brief": "Fabrikasjon av traverskraner, svingkraner og monorail-kranstrukturer — levert med FEM statisk beregning og CE-ytelseserklæring (DoP).",
 "home_svc_r8_name": "Trykkbeholdere og prosesstanker",
 "home_svc_r8_brief": "Lagertanker, reaksjonsbeholdere og varmevekslere etter PED kat. I–II — komplett dokumentpakke med RT + UT + CE-erklæring.",
 "trace_step_label": "TRINN",
 "trace_step1_title": "Ordre og engineering",
 "trace_step1_dur": "1–3 dager",
 "trace_step1_chip": "TRINN 01 · SOP.REV.ENG",
 "trace_step1_h": "Teknisk tegning mottas, arbeidsordre åpnes.",
 "trace_step1_body": "DWG-/DXF-/PDF-filer fra kunden gjennomgås av ingeniørteamet vårt. Hver arbeidsordre tildeles et unikt serienummer, og produksjonsløpet, WPS-valget og NDT-planen fastsettes i dette trinnet.",
 "trace_step1_d1": "Arbeidsordre",
 "trace_step1_d2": "Produksjonstegning",
 "trace_step1_d3": "WPS-valg",
 "trace_step1_d4": "NDT-plan",
 "trace_step2_title": "Materialmottak og smelte",
 "trace_step2_dur": "1 dag",
 "trace_step2_chip": "TRINN 02 · MAT.INCOMING",
 "trace_step2_h": "Platens smeltenummer registreres med 3.1-sertifikat.",
 "trace_step2_body": "S355 J2+N-plate fra Metalurji A.Ş.; smelte A41E2 registrert med MTC-2026-4182 (EN 10204 3.1). Etter VT og tykkelseskontroll merkes platen med arbeidsordre JOB-A142.",
 "trace_step2_d1": "Materialsertifikat",
 "trace_step2_d2": "Visuell kontroll",
 "trace_step2_d3": "Tykkelsesmåling",
 "trace_step2_d4": "Smelteregistrering",
 "trace_step3_title": "Kutting og bøying",
 "trace_step3_dur": "1–2 dager",
 "trace_step3_chip": "TRINN 03 · CUT.FORM",
 "trace_step3_h": "CNC-kutting, toleransekontroll, bøying.",
 "trace_step3_body": "Platene kuttes med CNC-plasma eller laser etter DXF; profiler klargjøres med riktige vinkler. Bøyene simuleres og utføres med korrekt vinkel. Hver del bærer fysisk arbeidsordre + smeltenummer.",
 "trace_step3_d1": "Kutteprogram",
 "trace_step3_d2": "Målrapport",
 "trace_step3_d3": "Kontroll av bøyevinkel",
 "trace_step3_d4": "Deletikett",
 "trace_step4_title": "Sveiset fabrikasjon",
 "trace_step4_dur": "3–10 dager",
 "trace_step4_chip": "TRINN 04 · WELDING.ACTIVE",
 "trace_step4_h": "Sertifisert sveiser, godkjent WPS.",
 "trace_step4_body": "Sveising utføres kun av sveisere som er sertifisert for den aktuelle prosedyren. Hver sveisesøm registreres digitalt med sveiserkode, WPS-nummer, antall strenger og tråd-/gassparametere. Forvarmings- og mellomstrengtemperatur overvåkes kontinuerlig.",
 "trace_step4_d1": "Sveisesertifikat",
 "trace_step4_d2": "WPS",
 "trace_step4_d3": "Sveiselogg",
 "trace_step4_d4": "Mellomstrengtemperatur",
 "trace_step5_title": "NDT / Inspeksjon",
 "trace_step5_dur": "1–3 dager",
 "trace_step5_chip": "TRINN 05 · NDT.INSPECT",
 "trace_step5_h": "Ikke-destruktiv testing: visuell, overflate, volumetrisk.",
 "trace_step5_body": "I henhold til NDT-planen: 100 % visuell kontroll (VT), penetrant (PT) eller magnetpulver (MT) på kritiske sveiser, ultralyd (UT) eller radiografi (RT) for volumetrisk kontroll. Rapporteres av nivå II-personell.",
 "trace_step5_d1": "VT-rapport",
 "trace_step5_d2": "PT-/MT-rapport",
 "trace_step5_d3": "UT-rapport",
 "trace_step5_d4": "Akseptkriterier",
 "trace_step6_title": "Overflate og belegg",
 "trace_step6_dur": "1–3 dager",
 "trace_step6_chip": "TRINN 06 · SURFACE.COAT",
 "trace_step6_h": "Sandblåsing, grunning, toppstrøk — C3-/C4-beskyttelse.",
 "trace_step6_body": "Delene forbehandles til blåsegrad Sa 2½; et malingssystem tilpasset korrosivitetskategorien påføres. Tørrfilmtykkelsen (DFT) måles og rapporteres for hvert strøk.",
 "trace_step6_d1": "Blåsegrad",
 "trace_step6_d2": "Malingssystem",
 "trace_step6_d3": "DFT-måling",
 "trace_step6_d4": "Farge / kode",
 "trace_step7_title": "Forsendelse og dokumentmappe",
 "trace_step7_dur": "1 dag",
 "trace_step7_chip": "TRINN 07 · SHIP.DOSSIER",
 "trace_step7_h": "Produkt + dokumentmappe leveres sammen.",
 "trace_step7_body": "Etter sluttkontroll pakkes produktet. En komplett dokumentpakke knyttet til arbeidsordren — WPS, WPQR, sveisesertifikater, materialsertifikater, NDT-rapporter, mål- og DFT-registreringer, CE-erklæring — leveres i én samlet fil.",
 "trace_step7_d1": "Følgeseddel",
 "trace_step7_d2": "Dokumentmappe (pdf)",
 "trace_step7_d3": "CE / DoP",
 "trace_step7_d4": "QR-sporingskort",
