 "home_doc_eyebrow": "06 / Dokumenteksempel",
 "home_doc_h2": "Hver leveranse inkluderer en <span style=\"color:var(--arc-2)\">dokumentmappe</span>: WPS, WPQR, NDT, sporing.",
 "home_doc_lede": "Vi leverer ikke bare deler — sammen med hver forsendelse leverer vi en komplett dokumentmappe som beviser hvordan delen ble produsert, hvem som sveiset den, hvilket råmateriale som ble brukt og hvilke inspeksjoner den har bestått.",
