 "testim_eyebrow": "02 / Referansestemmer",
 "testim_h2": "Tilbakemeldinger fra kunder <span style=\"color:var(--arc-2)\">bekrefter prosjektkvaliteten.</span>",
 "tm1_q": "Det var første gang vi jobbet med en leverandør der dokumentpakken kom så komplett. Vi satt ikke igjen med noen spørsmålstegn etter revisjonen på byggeplassen — alle WPS-er, NDT- og materialregistreringer var klare.",
 "tm1_role": "Kvalitetssjef · Energi-OEM",
 "tm2_q": "For serieproduksjon av skuffer forventet vi både punktlighet og repeterbar kvalitet. ArmaWeld har levert denne disiplinen konsekvent i tre år.",
 "tm2_role": "Innkjøpssjef · OEM for tungt utstyr",
 "tm3_q": "På trykkbeholderprosjektet vårt jobbet vi med ett og samme team fra designfasen til CE-ytelseserklæringen. Idriftsettelsen gikk gjennom uten problemer.",
 "tm3_role": "Prosjektingeniør · Kjemisk anlegg",
