 "sec5_desc": "For jernbanesektoren: kjøretøyoverbygg etter EN 15085 CL1/CL2; for forsvaret: slitasje- og støtbestandige panserkonstruksjoner. Kostnaden ved én enkelt svikt er høy på disse områdene; derfor anvendes vårt strengeste akseptkriterium (EN ISO 5817 B) og 100 % NDT.",
