 "about_flow_head_t": "<b>■</b>PROSESSFLYT · ARMAWELD-01",
 "about_flow_head_r": "ENVEIS · INGEN RETUR",
 "about_flow_st1_title": "Materialmottak",
 "about_flow_st1_sub": "Sertifikat · Materialprøve fra verk · Smeltenr.-avstemming",
 "about_flow_st1_kpi": "EN 10204 · 3.1",
