 "about_flow_st3_sub": "MIG/MAG · TIG · MMA · Godkjent WPS",
 "about_flow_st3_kpi": "WPS · WPQR",
 "about_flow_st4_title": "NDT &amp; inspeksjon",
 "about_flow_st4_sub": "VT · PT · MT · UT · Geometrisk kontroll",
 "about_flow_st4_kpi": "VT · UT · PT · MT · RT",
 "about_flow_st5_title": "Forsendelse",
