 "about_flow_st5_kpi": "Komplett leveringsmappe",
 "about_flow_foot_l": "TOTALT 05 STASJONER",
 "about_flow_foot_r": "● I DRIFT",
 "quality_cert1_p": "Det grunnleggende kvalitetsrammeverket for sveiset fabrikasjon. Omfatter tilsyn fra sveiseingeniør, WPS, WPQR, sveisesertifisering, inspeksjonsplan og full sporbarhet.",
 "quality_cert2_p": "Produksjonskontroll i fabrikk (FPC) som kreves for fabrikasjon av bærende stålkonstruksjoner. EXC3 omfatter konstruksjoner med store konsekvenser ved svikt.",
 "quality_cert3_p": "Vårt sentrale styringsrammeverk basert på prosessledelse, kundefokus, risikobasert tenkning og kontinuerlig forbedring.",
 "quality_cert7_h3": "Miljøstyringssystem",
 "quality_cert7_p": "Avfallshåndtering, energi- og ressurseffektivitet, kontroll av miljøpåvirkning. Alt avfall fra kutting, sveising og overflatebehandling registreres og leveres via godkjente mottak.",
 "quality_cert8_h3": "Styringssystem for arbeidsmiljø",
 "quality_cert8_p": "Risikovurdering, arbeidstillatelsessystemer, håndtering av personlig verneutstyr og vernerunder. Eksponering for sveiserøyk, trange rom og arbeid i høyden styres etter prosedyre.",
 "quality_cert4_p1": "<strong style=\"color:var(--bone)\">15614-1</strong> — WPQR for buesveising av stål, nikkel og nikkellegeringer. Godkjente prosedyrer for hver materialgruppe fra S235 til Strenx 1100, inkludert trykkbeholderstål i P-gruppen.",
 "quality_cert4_p2": "<strong style=\"color:var(--bone)\">15614-2</strong> — WPQR for buesveising av aluminium og aluminiumslegeringer. Fullt gjennomsveisede buttsveiser i EN AW-5754 (AlMg3) og EN AW-6082 (AlSi1MgMn) med TIG (141).",
 "quality_cert5_p1": "<strong style=\"color:var(--bone)\">9606-1</strong> — Sveisesertifikat for stål og rustfritt stål. Separate godkjenninger etter prosess (MAG 135, TIG 141, MMA 111), materialgruppe, posisjon og tykkelse. Gjennomgås hver 6. måned, fornyes hvert 2. år.",
 "quality_cert5_p2": "<strong style=\"color:var(--bone)\">9606-2</strong> — TIG-sveisesertifikat (141) for aluminiumslegeringer. Gyldig for gruppene FM21 (Al-Mg) og FM22 (Al-Si-Mg) i posisjonene PA · PB · PF.",
 "quality_cert6_p": "Internasjonal kvalifikasjonsstandard for personell som utfører, tolker og rapporterer NDT-inspeksjoner.",
 "quality_process_lede": "Sporbarheten går tapt i det øyeblikket ett av følgende sju ledd mangler. I systemet vårt kan intet ledd starte arbeidet uten registreringen fra det forrige.",
 "quality_pf1_t": "Teknisk mottak",
 "quality_pf1_d": "Gjennomgang av DWG/DXF/PDF, utstedelse av arbeidsordre og tildeling av serienummer.",
 "quality_pf2_t": "Materialmottak",
 "quality_pf2_d": "Smeltenummer + 3.1-sertifikat + visuell kontroll. Merking av plater.",
 "quality_pf3_t": "Kutting og bøying",
 "quality_pf3_d": "CNC-kutting, målkontroll, verifisering av bøyevinkel. Merking av deler.",
 "quality_pf4_t": "Sveiseoperasjon",
 "quality_pf4_d": "Sertifisert sveiser + WPS + logg over mellomstrengtemperatur.",
 "quality_pf5_t": "NDT-inspeksjon",
 "quality_pf5_d": "Rapport fra nivå 2-personell + akseptkriterium EN ISO 5817 B.",
 "quality_pf6_t": "Overflate og maling",
 "quality_pf6_d": "Sa 2½ sandblåsing + malingssystem + DFT-målerapport.",
 "quality_pf7_t": "Dokumentmappe",
 "quality_pf7_d": "Alle registreringer leveres sammen med produktet, digitalt og på papir.",
 "quality_sim_h4": "Eksempeldokumenter",
