 "quality_sim_tab_dop": "CE / DoP",
 "quality_kpi1_h": "NDT godkjent ved første kontroll",
 "quality_kpi2_h": "First Pass Yield (FPY)",
 "quality_kpi3_h": "Levering til rett tid",
 "quality_kpi4_h": "Kundereturrate",
 "quality_kpi1_delta": "▲ 0,4 pp — mot 2025",
