 "quality_kpi4_delta": "▼ 0,2 pp — forbedring",
 "quality_cta_p": "Last ned den tekniske eksempelmappen med WPS-sammendrag, WPQR-referanse, materialsertifikat og NDT-rapport. Med hver prosjektleveranse mottar dere den utfylte versjonen av denne pakken.",
 "quality_cta_note": "HTML · UTSKRIFTSVENNLIG · EKSEMPELINNHOLD",
 "quality_cta_btn_full": "Åpne eksempelfil <span style=\"margin-left:8px;\">↓</span>",
 "ndt_scope_in_k": "I EGET HUS",
 "ndt_scope_in_sub": "Personell sertifisert etter ISO 9712 nivå II · intern rapportering · full sporbarhet",
 "ndt_scope_out_k": "EKSTERNT",
 "ndt_scope_out_sub": "Krever strålevernlisens. Utføres med vår autoriserte, lisensierte laboratoriepartner — film-/digitalrapporter arkiveres direkte i prosjektmappen.",
 "ndt_detects_h": "Feil som påvises",
 "ndt_vt_i": "// 01 · VT — VISUELL KONTROLL",
 "ndt_vt_p": "Det første, mest grunnleggende og viktigste trinnet i enhver inspeksjon. Sveisen vurderes visuelt med speil, LED-lamper, sveisemål og digitale mikroskoper. Utføres ved 20 °C under ≥ 350 lux belysning.",
 "ndt_vt_sub": "Visuell inspeksjon",
 "ndt_vt_st1": "Overflaterengjøring og oppsett av belysning",
 "ndt_vt_st2": "Geometrikontroll før sveising",
 "ndt_vt_st3": "Oppfølging mellom strengene",
 "ndt_vt_st4": "Sluttkontroll (≥ 350 lux)",
 "ndt_vt_st5": "Måling og registrering",
 "ndt_vt_d1": "Overflatesprekker (makro)",
 "ndt_vt_d2": "Avvik i sveisegeometri (høyde, lengde, kant)",
 "ndt_vt_d3": "Sårkant",
 "ndt_vt_d4": "Sprut, overflatemerker, ruhet",
 "ndt_vt_d5": "Kantforskyvning, gjennomsig",
 "ndt_vt_d6": "Feil i rotgjennomtrengning (der det er tilgjengelig)",
 "ndt_vt_c1": "Overflatefølsomhet",
 "ndt_vt_c2": "Geometrikontroll",
 "ndt_pt_i": "// 02 · PT — PENETRANTPRØVING",
 "ndt_pt_p": "En penetrerende væske trenger inn i sprekker som bryter overflaten ved kapillærvirkning; etter vask og påføring av fremkaller trekkes indikasjonen ut og blir synlig. Uunnværlig for ikke-magnetiske materialer (rustfritt stål, aluminium, kobberlegeringer).",
 "ndt_pt_sub": "Penetrantprøving",
 "ndt_pt_st1": "Overflaterengjøring",
 "ndt_pt_st2": "Påføring av penetrant",
 "ndt_pt_st3": "Virketid (≥ 20 min)",
 "ndt_pt_st4": "Vask og fremkaller",
 "ndt_pt_st5": "Inspeksjon og registrering",
 "ndt_pt_d1": "Sprekker som bryter overflaten (varme, kalde)",
 "ndt_pt_d2": "Porer og kratere som bryter overflaten",
 "ndt_pt_d3": "Usammensmeltede fugelinjer",
 "ndt_pt_d4": "Fine overflatefeil (&gt;1 µm)",
 "ndt_pt_c1": "Påvisning av overflatesprekker",
 "ndt_pt_c2": "Anvendelige materialer",
 "ndt_pt_c3": "Volumetrisk påvisning",
 "ndt_mt_i": "// 03 · MT — MAGNETPULVERPRØVING",
 "ndt_mt_p": "Når et magnetfelt påføres ferromagnetisk materiale, trekkes jernpartikler mot lekkasjefluksen rundt feil i overflaten og like under den (2–3 mm). Foretrekkes fremfor PT på karbonstål og lavlegert stål.",
 "ndt_mt_sub": "Magnetpulverprøving",
 "ndt_mt_st1": "Magnetisering med åk",
 "ndt_mt_st2": "Påføring av partikler (våt/tørr)",
 "ndt_mt_st3": "Inspeksjon i UV-/hvitt lys",
 "ndt_mt_st4": "Avmagnetisering",
 "ndt_mt_st5": "Registrering",
 "ndt_mt_d1": "Sprekker i og like under overflaten",
 "ndt_mt_d2": "Kaldt overlapp",
 "ndt_mt_d3": "Poreansamlinger nær overflaten (grunne)",
 "ndt_mt_d4": "Valse-/lamineringsfeil",
 "ndt_mt_c1": "Nær overflaten (≤2 mm)",
 "ndt_ut_i": "// 04 · UT — ULTRALYD (I EGET HUS)",
 "ndt_ut_p": "Høyfrekvente lydbølger går gjennom materialet og reflekteres når de treffer en diskontinuitet (feil, indre overflate). Den sikreste og mest økonomiske metoden for å påvise volumetriske (indre) feil. På tykke plater er den langt tryggere enn RT (ingen stråling). <strong>Utføres av vårt personell sertifisert etter ISO 9712 nivå II</strong> — rapportering i eget hus.",
 "ndt_ut_sub": "Ultralydprøving",
 "ndt_ut_st1": "Kalibrering (referanseblokk)",
 "ndt_ut_st2": "Skanning (A-skann puls-ekko)",
 "ndt_ut_st3": "Ekkovurdering",
 "ndt_ut_st4": "Feilstørrelse og -posisjon",
 "ndt_ut_st5": "Rapport og aksept/avvisning",
 "ndt_ut_d1": "Indre sprekker (alle orienteringer)",
 "ndt_ut_d2": "Manglende gjennomtrengning, bindefeil",
 "ndt_ut_d3": "Volumetriske feil (store porer, slagginneslutninger)",
 "ndt_ut_d4": "Laminering (valsing)",
 "ndt_ut_d5": "Alle feil klassifisert som volumetriske i ISO 5817",
 "ndt_ut_c1": "Påvisning av volumetriske feil",
 "ndt_ut_c2": "Påvisningsdybde",
 "ndt_ut_c3": "Overflatefeil",
 "ndt_rt_i": "// 05 · RT — RADIOGRAFI (EKSPONERING: PARTNER · VURDERING: I EGET HUS)",
 "ndt_rt_p": "Røntgen- eller gammastråling går gjennom materialet og svekkes ulikt ved feil, slik at de blir synlige på film eller digitale detektorer. Filmeksponeringen utføres av et lisensiert partnerselskap; filmvurdering og rapportering gjøres av vårt eget RT-personell sertifisert etter EN ISO 9712 nivå 2, og rapportene legges inn i jobbmappen deres.",
 "ndt_rt_sub": "Radiografisk prøving",
 "ndt_rt_st1": "Klargjøring av kilde og områdesikring",
 "ndt_rt_st2": "Plassering av film / digital detektor",
 "ndt_rt_st3": "Eksponering (røntgen / gamma)",
 "ndt_rt_st4": "Filmfremkalling / digital avlesning",
 "ndt_rt_st5": "Bildetolkning og rapport",
 "ndt_rt_d1": "Volumetriske feil (porøsitet, slagginneslutninger)",
 "ndt_rt_d2": "Plane feil (sprekker) — ved gunstig orientering",
 "ndt_rt_d3": "Manglende gjennomtrengning, bindefeil",
 "ndt_rt_d4": "Reaksjoner og uregelmessigheter på innvendig overflate",
 "ndt_rt_c1": "Påvisning av volumetriske feil",
 "ndt_rt_c2": "Overflatefeil",
 "ndt_rt_c3": "Uavhengig av tykkelse",
 "ndt_foot_in": "UTFØRES I EGET HUS",
 "ndt_foot_out": "EKSPONERING: LISENSIERT PARTNER · VURDERING: NIVÅ 2 I EGET HUS",
 "ndt_foot_op": "● I DRIFT",
 "ndt_foot_partner": "● PARTNERLAB",
 "ndt_def1_h": "Sprekk",
 "ndt_def1_p": "En separasjon forårsaket av tap av kohesjon. Kan være varm (størkning) eller kald (hydrogen). Den farligste feilklassen.",
 "ndt_def2_h": "Porøsitet",
 "ndt_def2_p": "Kuleformede hulrom forårsaket av gass som fanges under størkning. Forebygges med ren dekkgass, tørre elektroder og ren overflate.",
 "ndt_def3_h": "Slagginneslutning",
 "ndt_def3_p": "Slaggrester som blir igjen i sveisen på grunn av utilstrekkelig rengjøring mellom strengene. Forebygges med disiplinert sliping/børsting i flerstrengssveiser.",
 "ndt_def4_h": "Bindefeil",
 "ndt_def4_p": "Manglende fullstendig sammensmelting mellom tilsettmateriale og grunnmateriale eller mellom strenger. Forårsakes av for lav strøm eller feil teknikk.",
 "ndt_def5_h": "Manglende gjennomtrengning",
 "ndt_def5_p": "Rotstrengen går ikke gjennom hele materialtykkelsen. Oppstår ved feil rotvinkel, rotåpning eller parametere for rotstrengen.",
 "ndt_def6_h": "Sårkant",
 "ndt_def6_p": "Et hakk/spor i grunnmaterialet ved sveisetåen. Forårsakes av for høy strøm eller feil pistolvinkel. Startpunkt for utmattingssprekker.",
 "ndt_accept_lede": "Ikke alle jobber inspiseres med samme strenghet. Avhengig av konstruksjonens risikoklasse anvendes akseptnivå B, C eller D etter EN ISO 5817. Med mindre annet er angitt, er ArmaWelds standard det strengeste, nivå B.",
