 "welding_mig_desc": "En halvautomatisk prosess med høy avsetting som bruker kontinuerlig matet tråd under dekkgass. Ryggraden i verkstedet vårt; førstevalg for kranstrukturer, stålkonstruksjoner og rammer til anleggsmaskiner.",
