 "legal_p_1": "ArmaWeld — Fevziçakmak Mah. 10758. Sk. No: 25/H, Karatay, Konya, Tyrkia<br/>E-post: <a href=\"mailto:info@armaweld.com\">info@armaweld.com</a> · Tlf.: <a href=\"tel:+905438400332\">+90 543 840 0332</a>",
 "legal_h2_2": "2. Personopplysninger som behandles",
 "legal_list_2": "<li>Identitet og kontakt: navn, firma, e-post, telefon, stilling</li><li>Innhold i henvendelsen: prosjektbeskrivelse, materiale, frist, budsjett, opplastede tekniske filer</li><li>Transaksjonssikkerhet: IP-adresse, nettleserdata, tidspunkt for skjemainnsending (loggdata)</li><li>Informasjonskapsler/analyse: anonym bruksstatistikk fra Google Analytics (etter samtykke)</li>",
 "legal_h2_3": "3. Formål med behandlingen",
 "legal_list_3": "<li>Utarbeidelse av tilbud og teknisk vurdering</li><li>Kommunikasjon og kundeoppfølging</li><li>Prekontraktuelle prosesser og NDA-forpliktelser</li><li>Oppfyllelse av rettslige forpliktelser</li><li>Måling av nettstedets ytelse (analyse etter samtykke)</li>",
 "legal_h2_4": "4. Rettslig grunnlag",
 "legal_p_4": "Opplysningene behandles med grunnlag i KVKK art. 5/2 (c) oppfyllelse av avtale, (f) berettiget interesse, (a) uttrykkelig samtykke (nyhetsbrev, analysekapsler) og (ç) rettslig forpliktelse.",
 "legal_h2_5": "5. Overføring",
 "legal_p_5": "Opplysningene deres kan bare deles med tjenesteleverandører som er nødvendige for tilbuds-/kontraktsprosessene (e-postinfrastruktur, hosting) og med myndigheter når loven krever det. Overføring til utlandet skjer i samsvar med KVKK art. 9.",
 "legal_h2_6": "6. Lagringstid",
 "legal_p_6": "Tilbuds- og prosjektdokumentasjon oppbevares i inntil <strong>10 år</strong> i henhold til handelsrettslige og juridiske forpliktelser; deretter slettes, tilintetgjøres eller anonymiseres den.",
 "legal_h2_7": "7. Deres rettigheter",
 "legal_p_7": "I henhold til KVKK art. 11 kan dere be om innsyn, retting, sletting, protestere mot behandlingen og kreve erstatning. Kontakt: <a href=\"mailto:info@armaweld.com\">info@armaweld.com</a>",
 "legal_h2_8": "8. Informasjonskapsler",
 "legal_p_8": "Nødvendige informasjonskapsler brukes for at nettstedet skal fungere. Analysekapsler aktiveres først etter deres samtykke. Administrer innstillingene via nettleseren eller nettstedets samtykkebanner.",
