 "home_persona_eyebrow": "01 / Hvem det er for",
 "home_persona_h2": "En tydelig prosess for <span style=\"color:var(--arc-2)\">tekniske beslutningstakere.</span>",
 "home_persona1_t": "Innkjøp / Forsyning",
 "home_persona1_d": "Tilbud innen 48 timer, fleksibel MOQ og klare leveringstider — dere ser prosessforpliktelser, ikke bare pris.",
 "home_persona1_l": "Tilbudsprosessen →",
 "home_persona2_t": "Kvalitet & Samsvar",
 "home_persona2_d": "WPS, WPQR, NDT-rapporter og materialsertifikater i leveransedokumentasjonen — ingen hull ved revisjon.",
 "home_persona2_l": "Dokumentpakke →",
 "home_persona3_t": "Prosjekt- / Produksjonsteknikk",
 "home_persona3_d": "Sveisemetode, varmetilførsel og toleranseplan fastsettes på tilbudsstadiet — færre overraskelser i verkstedet.",
 "home_persona3_l": "Produksjonsplan →",
 "home_aud_eyebrow": "02 / Hvem vi betjener",
 "home_aud_h2": "OEM-er, EPC-er og <span style=\"color:var(--arc-2)\">fabrikasjonspartnere.</span>",
 "home_aud1_t": "Maskin- og utstyrs-OEM",
 "home_aud1_d": "Serie- og prototypeproduksjon av sveiste karosserier, skuffer, bommer og slitedeler.",
 "home_aud2_t": "Energi- og prosessanlegg",
 "home_aud2_d": "Trykkbeholdere, plattformer og stålkonstruksjoner — dokumentert produksjon under PED og EN 1090.",
 "home_aud3_t": "Bygg- og infrastrukturentreprenører",
 "home_aud3_d": "EXC3-konstruksjonsstål, montasjestøtte og byggeplassklare delesett.",
 "home_blog_eyebrow": "08 / Teknisk innsikt",
 "home_blog_h2": "Notater fra <span style=\"color:var(--arc-2)\">sveiseteknikken.</span>",
 "home_blog1_t": "Hva er WPS og WPQR?",
 "home_blog1_d": "En sveis uten godkjent prosedyre — det første punktet som feiler ved revisjon.",
 "home_blog2_t": "EN 1090 EXC3 i praksis",
 "home_blog2_d": "Hva produksjonskontroll, sporbarhet og CE-dokumentasjonen faktisk krever.",
 "home_blog3_t": "NDT-metoder — kort guide",
 "home_blog3_d": "VT, PT, MT, UT — hvilken metode for hvilken feil.",
 "home_certs_eyebrow": "09 / Sertifiseringer",
 "home_certs_h2": "<span style=\"color:var(--arc-2)\">Dokumentryggraden</span> i reviderbar produksjon.",
 "home_certs_lede": "Hvert prosjekt bygger på godkjente WPS-er, sertifisert personell og sporbare kvalitetsregistreringer. Standardene nedenfor vedlikeholdes aktivt.",
 "home_certs_link": "Kvalitetsprosess og dokumentpakke →",
 "proj1_outcome": "Serieproduksjon av skuffer med repeterbar WPS og VT/MT-plan per del.",
 "proj2_outcome": "Hovedbæresystem for lagerbygg med EXC2/EXC3-dokumentasjon og dimensjonsrapport.",
 "proj3_outcome": "Reaktor under PED med TIG/MIG-WPS, 100 % RT og CE-dokumentasjon.",
 "proj4_outcome": "Solcellestruktur med varmforsinket belegg, toleransekontroll på kutt og montasjestøtte.",
 "proj5_outcome": "Boggiramme med dokumentasjonskjede etter EN 15085 CL1 og 100 % UT.",
 "proj6_outcome": "Plattform, trapper og rekkverk — levert med montasjeliste og overflateforbehandling.",
 "services_s01_benefit": "Hver sveis dokumentert med godkjent WPS.",
 "services_s02_benefit": "Sveiseklare kanter og toleransekontroll.",
 "services_s03_benefit": "Montasjepasning gjennom bøyesimulering.",
 "why_eyebrow": "07 / Hvorfor ArmaWeld",
 "why_h2": "Prosedyredisiplin, <span style=\"color:var(--arc-2)\">ikke markedsføring.</span>",
 "why1_t": "Rammeverk etter EN ISO 3834-2",
 "why1_d": "Kvalitetsstyring av sveising er daglig rutine — ikke en spesiell prosjektmodus.",
 "why2_t": "EXC3-konstruksjonsstål",
 "why2_d": "Produksjonskontroll, sporbarhet og CE-dokumentasjon fra én datakjede.",
 "why3_t": "4 NDT-metoder internt",
 "why3_d": "VT, PT, MT, UT — personell nivå 2; RT via partner ved behov.",
 "why4_t": "Tilbuds-SLA på 48 timer",
 "why4_d": "Material- og prosedyrevalg skriftlig i tilbudet — ikke muntlige løfter.",
 "footer_capability": "EN ISO 3834-2 · EN 1090 EXC3 · 4 NDT-metoder · tilbud innen 48 timer",
 "cap_title_tag": "Produksjonskapasitet — ArmaWeld | EN 1090 EXC3 · EN ISO 3834-2",
 "cap_meta_desc": "ArmaWelds produksjonskapasitet: EN 1090 EXC3-konstruksjonsstål, sveisekvalitet etter EN ISO 3834-2, materialgrupper, NDT og tilbud innen 48 timer. Anlegg i Konya.",
 "cap_h1": "Produksjonskapasitet<br/><span class=\"arc\">Konya · integrert anlegg</span>",
 "cap_updated": "Sist oppdatert: mai 2026",
 "cap_intro": "Denne siden oppsummerer hva vi faktisk produserer ved anlegget vårt i Konya. Vi deler sertifikater, material-/prosessomfang og arbeidsflyten fra tilbud til levering — ikke en oppblåst maskinliste.",
 "cap_cert_h": "Sertifikater & omfang",
 "cap_cert_p": "EN 1090-2 EXC3 (konstruksjonsstål), EN ISO 3834-2 (sveisekvalitet), ISO 9001:2015 (kvalitet), ISO 14001:2015 (miljø), ISO 45001:2018 (arbeidsmiljø og sikkerhet). WPQR-basert WPS-bibliotek; sveisere etter EN ISO 9606-1/2. NDT-personell EN ISO 9712 nivå 2.",
 "cap_mat_h": "Materialgrupper",
 "cap_mat_p": "S235–S960QL, slitestål Strenx/HARDOX, S700MC, rustfritt 304/316L og utvalgte aluminiumslegeringer — godkjent WPS og varmekontroll per gruppe.",
 "cap_proc_h": "Prosesser",
 "cap_proc_p": "MIG/MAG, TIG, SMAW; CNC-plasma-/laser-/giljotinkutting; knekking i kantpresse; mekanisk montasje. VT, PT, MT, UT på kritiske sveiser; RT via partnerlaboratorium.",
 "cap_sla_h": "Tilbud & levering",
 "cap_sla_p": "Skriftlig tilbud innen 48 timer i gjennomsnitt etter tegningsgjennomgang: materiale, WPS-sammendrag, NDT-plan og leveringstid. NDA som standard; koordinering av eksportforsendelse tilgjengelig.",
 "cap_contact_h": "Send tekniske filer",
 "cap_contact_p": "Bruk kontaktskjemaet eller info@armaweld.com med DWG/DXF/PDF og materialinformasjon — engineering svarer innen 48 timer.",
 "footer_cap_link": "Kapasitetsprofil →",
 "services_cta_p": "Send tegninger eller en prøve — vi utarbeider kostnadsanalyse og produksjonsplan innen 48 timer.",
 "footer_legal": "Innhold, bilder og varemerker på dette nettstedet tilhører ArmaWeld. Reproduksjon eller bruk uten tillatelse er forbudt.",
 "home_ref_q1": "Tidligere leverandører som sveiset S960QL, hoppet over forvarmingen — vi fikk sprekker. Hos ArmaWeld var WPS-en og forvarmingsprotokollen komplett.",
 "home_ref_q1_who": "INNKJØPSSJEF · OEM TUNGE KJØRETØY",
 "home_ref_q2": "Vi ba om dokumentpakken for EN 1090 EXC3. CE-dokumentasjon, WPQR-liste, NDT-rapporter — alt klart ved første levering.",
 "home_ref_q2_who": "KVALITETSINGENIØR · ENERGIANLEGG",
 "home_ref_q3": "Vi har bestilt skuffer i serie hvert år i tre år. Kvalitetsvariasjonen fra del til del er nær null — den disiplinen er vanskelig å opprettholde.",
 "home_ref_q3_who": "DAGLIG LEDER · MASKINPRODUKSJON",
