 "saw35_p2_h": "Forberedelse og hefting",
 "saw35_p2_p": "Fugeforberedelse, spalte og fiksturering kontrolleres; lange deler heftes innenfor retthetstoleransen.",
 "saw35_p3_h": "Pulverbuesveising",
 "saw35_p3_p": "Sømmen sveises kontinuerlig på 35 m-linjen etter WPS-parameterne; strøm, spenning og hastighet registreres.",
 "saw35_p4_h": "Kontroll og dokumentasjon",
 "saw35_p4_p": "Visuell kontroll og påkrevd NDT utføres; målrapport, materialsertifikater og sveiseregistreringer følger delen ved levering.",
 "saw35_sec_label": "Bransjer",
