 "saw35_s6_d": "Langsgående skallsømmer",
 "saw35_faq_label": "FAQ",
 "saw35_faq_h2": "FAQ om pulverbuesveising",
 "saw35_q1": "Hva er pulverbuesveising?",
 "saw35_a1": "Pulverbuesveising (SAW, ISO 4063-121) er en automatisert lysbueprosess der lysbuen mellom en kontinuerlig matet tråd og arbeidsstykket brenner under granulert pulver. Pulveret beskytter lysbuen og smeltebadet og gir høy avsmelting og dyp innbrenning.",
 "saw35_q2": "Hva gir en 35 m SAW-maskin?",
 "saw35_a2": "Lange deler kan sveises i én oppspenning. Hastighet og parametere holdes konstante langs hele sømmen, slik at kvaliteten blir repeterbar, antall start-/stopp-punkter og tilhørende feilrisiko reduseres, og tiden til omposisjonering kuttes.",
 "saw35_q3": "Hvilke deler egner seg for pulverbuesveising?",
 "saw35_a3": "Middels tunge og tunge ståldeler med lange, rette sømmer som kan sveises horisontalt (PA) eller som horisontale kilsveiser (PB): bommer, chassisvanger, sveisede I-bjelker, kassesøyler, buttskjøter i plate og tankskall. MAG er det bedre valget for svært korte sømmer og tynnplate.",
 "saw35_q4": "Tilbyr dere SAW på kontrakt?",
 "saw35_a4": "Ja. Vi sveiser bommer, chassis og langsømdeler til produktene deres etter deres tegninger. Delene kan komme inn kun for sveising, eller prises som komplett fabrikasjon inkludert kutting, bøying, sveising og NDT.",
 "saw35_q5": "Hva trenger dere for å gi et tilbud?",
 "saw35_a5": "Tegning (PDF/DXF/STEP), stålkvalitet og tykkelse, sømlengder, antall og eventuelt kvalitetsklasse (EN 1090 EXC, EN ISO 5817) og NDT-krav.",
 "saw35_blog_label": "Tekniske veiledninger",
 "saw35_cta_h2": "La oss gå gjennom langsømdelene deres sammen",
 "saw35_cta_p": "Send oss tegningen av bommen, chassiset eller langsømjobben deres, så utarbeider vi et tilbud på pulverbuesveising.",
 "saw35_cta_services": "Alle tjenester",
 "saw35_rel1": "Pulverbuesveisemaskiner for bommer, chassis og lange sømmer",
 "saw35_rel3": "Sveisedeformasjon: metoder for forebygging og retting",
