 "kf_s1_label": "Tjenester innen sveising på kontrakt",
 "kf_s1_title": "Sveiset fabrikasjon som leieproduksjon fra Konya",
 "kf_s1_desc": "Serie- eller batchproduksjon utføres etter OEM-kundens tegninger og spesifikasjoner. Hver prosess er dokumentert og sertifisert.",
 "kf_c1_icon": "MIG / MAG",
 "kf_c1_h": "MIG/MAG-sveising",
