 "kf_c4_icon": "Bøying",
 "kf_c4_h": "CNC-bøying",
 "kf_c4_p": "V/U-bøying og platevalsing. Programmerte vinkler, kompensasjon for tilbakefjæring og prosessplanlegging med fokus på monteringspasning.",
 "kf_c5_icon": "Montering",
 "kf_c5_h": "Mekanisk montering",
 "kf_c5_p": "Montering av kontraktsdeler, kontroll av boltemoment og pakking klar for byggeplass.",
 "kf_c6_icon": "NDT / kvalitet",
 "kf_c6_h": "Kvalitet & NDT",
 "kf_c6_p": "VT, PT, MT og UT internt. Prosedyrer, sveiserkvalifisering og leveransedokumentasjon iht. ISO 3834-2.",
 "kf_s2_label": "Produksjonsomfang",
 "kf_s2_title": "Prosesskapasitet",
 "kf_s2_desc": "Fra anlegget vårt i Konya får kontraktskunder en integrert tjeneste fra kutting til leveransedokumentasjon. Vi oppgir sertifiserings- og prosedyreomfang fremfor antall maskiner.",
 "kf_th1": "Område",
