 "kf_st1_h": "Teknisk avklaring",
 "kf_st1_p": "Godkjenning av tegninger, toleranser og stykkliste. NDA kan signeres.",
 "kf_st2_h": "Prøve & FAI",
 "kf_st2_p": "Førstegangskontroll (First Article Inspection). Serieproduksjonen starter ikke uten kundens godkjenning.",
 "kf_st3_h": "Serieproduksjon",
 "kf_st3_p": "Ukentlig eller månedlig batchplanlegging. Lager- og JIT-levering er tilgjengelige alternativer.",
 "kf_st4_h": "Kvalitetsregistreringer & levering",
