 "kf_s4_label": "Bransjer",
 "kf_s4_title": "Bransjer vi betjener",
 "kf_s4_desc": "De viktigste bransjene vi leverer sveiset fabrikasjon på kontrakt til fra Konya, i Tyrkia og for eksport:",
 "kf_sec1_h": "Forsvar",
 "kf_sec1_p": "Strukturer til pansrede kjøretøy, komponenter til taktiske plattformer",
 "kf_sec2_h": "Landbruksmaskiner",
 "kf_sec2_p": "Ploger, såmaskiner, tilhengere, chassis til skurtreskere",
 "kf_sec3_h": "Energi",
 "kf_sec3_p": "Vindturbiner, vannkraft, energiinfrastruktur",
 "kf_sec4_h": "Bygg og anlegg",
 "kf_sec4_p": "Stålkonstruksjoner iht. EN 1090 EXC2/EXC3",
 "kf_sec5_h": "Gruvedrift",
 "kf_sec5_p": "Transportører, siktutstyr, slitasjeplater",
 "kf_sec6_h": "Bilindustrileverandører",
 "kf_sec6_p": "Chassis, braketter, delmontasjer",
 "kf_s5_label": "Ofte stilte spørsmål",
 "kf_s5_title": "Sveising på kontrakt i Konya: FAQ",
 "kf_f1_q": "Hvor kan jeg få sveising på kontrakt i Konya?",
 "kf_f1_a": "ArmaWeld er et EN 1090- og ISO 3834-2-sertifisert selskap for sveising på kontrakt og fabrikasjon, med base i Konya. Vi produserer for OEM-er med MIG/MAG, TIG og robotsveising.",
 "kf_f2_q": "Hva er minste ordrekvantum for sveising på kontrakt?",
 "kf_f2_a": "Minste antall avhenger av prosjektkravene og delens kompleksitet. Dere kan også be om tilbud på prøver og små serier; vi avklarer først de tekniske detaljene og gjennomfører deretter en FAI.",
 "kf_f3_q": "Hvilke materialer sveiser dere?",
 "kf_f3_a": "Hovedmaterialene våre er karbonstål (S235–S960), rustfritt stål (304, 316L, duplex), aluminiumslegeringer (5083, 6082) og høyfaste stål som Hardox og Strenx.",
 "kf_f4_q": "Kan vi signere en konfidensialitetsavtale (NDA)?",
 "kf_f4_a": "Ja. Signering av NDA for å beskytte kundenes design og tekniske data er standard praksis. Langsiktige rammeavtaler er også mulig.",
 "kf_f5_q": "Hvilke dokumenter følger med hver leveranse?",
 "kf_f5_a": "Hver leveranse inkluderer målrapport, NDT-rapport (der det kreves), materialsertifikat (EN 10204 3.1) og en samsvarserklæring for sveiseprosedyren.",
 "kf_s6_label": "Sveiseoppdrag på kontrakt",
 "kf_s6_title": "Hvilke sveiseoppdrag tar vi på oss?",
 "kf_s6_desc": "Enkeltstykker, prøver eller serier sveist på kontrakt etter deres tegninger. Kutting, bøying, sveising, kontroll og leveransedokumentasjon fra én leverandør.",
 "kf_j1_h": "Maskinrammer og hus",
 "kf_j1_p": "Rammer, hus, chassis og spesialfiksturer for OEM-er, produsert i serie eller som enkeltstykker med repeterbar kvalitet.",
 "kf_j2_h": "Deler til anleggsmaskiner",
 "kf_j2_p": "Skuffer, bommer, bakre støtfangere og lasteplan i høyfaste stål som HARDOX, Strenx og S700MC.",
 "kf_j3_h": "Komponenter til stålkonstruksjoner",
 "kf_j3_p": "Søyler, bjelker, takstoler, plattformer og trapper iht. EN 1090-2 EXC1–EXC3, CE-merket.",
 "kf_j4_h": "Langsømdeler",
 "kf_j4_p": "Lange rette sømmer på bommer, kassebjelker og chassis, sveist på vår <a href=\"tozalti-kaynak.html\">35 m pulverbuesveisemaskin</a>.",
 "kf_j5_h": "Deler i rustfritt stål og aluminium",
 "kf_j5_p": "TIG-sveiste hus og deler til prosessutstyr i rustfritt stål 304 og 316L og aluminium 5083 og 6082.",
 "kf_j6_h": "Pakker med kutting + bøying + sveising",
 "kf_j6_p": "Laserkutting, CNC-bøying, sveising og mekanisk montering i én ordre; delene kommer klare til montering.",
 "kf_s7_label": "Hvorfor ArmaWeld?",
 "kf_s7_title": "Sertifisert, sporbar sveising på kontrakt",
 "kf_w1_h": "Sertifisert sveising",
 "kf_w1_p": "EN 1090 EXC3 og EN ISO 3834-2, med godkjent WPS/WPQR og sveisere kvalifisert iht. EN ISO 9606-1.",
 "kf_w2_h": "Intern kontroll",
 "kf_w2_p": "VT, PT, MT og UT utføres internt av personell med ISO 9712 nivå 2.",
 "kf_w3_h": "Tilbud innen 48 timer",
 "kf_w3_p": "Send tegning og antall, så får dere tilbud innen 48 timer; NDA er standard.",
 "kf_w4_h": "Følg ordren live",
 "kf_w4_p": "Produksjonstrinn, dokumenter og forsendelser i <a href=\"musteri-portali.html\">kundeportalen</a>.",
 "kf_s8_label": "Relaterte sider",
 "kf_s8_title": "Mer om vår tjeneste for sveising på kontrakt",
 "kf_l1": "MIG/MAG- og TIG-sveiseprosesser",
 "kf_l2": "Pulverbuesveising (35 m)",
 "kf_l3": "Ikke-destruktiv testing (NDT)",
 "kf_l4": "Kvalitet og sporbarhet",
 "kf_l5": "Slik velger dere leverandør av sveising på kontrakt",
 "kf_l6": "Hva er leieproduksjon av sveising? Fordeler og prosess",
 "kf_f6_q": "Hvordan beregnes prisen på sveising på kontrakt?",
 "kf_f6_a": "Prisen avhenger av materiale, sveiselengde, antall, behov for kutting og bøying, NDT-omfang og dokumentasjonskrav. Send tegning og antall, så mottar dere tilbud innen 48 timer.",
 "kf_f7_q": "Kan jeg bestille sveising på kontrakt fra utenfor Konya?",
 "kf_f7_a": "Ja. Vi produserer for kunder i hele Tyrkia og i utlandet fra anlegget vårt i Konya; frakt- og leveringsbetingelser avtales på tilbudsstadiet.",
 "px_home_fason": "<span class=\"hf-lbl\">Trenger dere deler sveist etter egne tegninger?</span><a href=\"konya-fason-kaynak.html\">Sveising på kontrakt i Konya</a>",
 "px_svc_fason": "Ønsker dere deler sveist etter egne tegninger? Se vår <a href=\"konya-fason-kaynak.html\">tjeneste for sveising på kontrakt i Konya</a>.",
 "kf_cta_h": "Deres partner for sveising på kontrakt i Konya",
 "kf_cta_p": "La oss gå gjennom et tilbud på kontraktsfabrikasjon for OEM-behovene deres sammen.",
 "kf_cta_more": "Tjenestedetaljer",
 "kf_s9_label": "For bedrifter som setter ut sveisearbeid",
 "kf_s9_title": "Dette bør dere vite før dere setter ut sveisearbeid",
 "kf_s9_desc": "De fire spørsmålene bedrifter som setter ut sveising stiller oftest: hva som styrer prisen, hva som skal sendes for tilbud, hvordan kvaliteten sikres og hvordan jobben følges opp.",
 "kf_b1_h": "Hva bør jeg sende for å få tilbud?",
 "kf_b1_p": "Teknisk tegning (DWG/DXF/STEP/PDF), stålkvalitet, antall, påkrevde dokumenter (3.1, NDT, DoP) og leveringsdato. Uten tegning er en prøvedel eller håndskisse nok til å komme i gang.",
 "kf_b2_h": "Hva styrer prisen på sveising på kontrakt?",
 "kf_b2_p": "Materiale, sveiselengde og -posisjon, antall, behov for kutting/bøying, NDT-omfang og dokumentsett. Tilbudet vårt spesifiserer disse som egne linjer; be om samme omfang når dere sammenligner leverandører.",
 "kf_b3_h": "Hvordan sikrer dere kvaliteten?",
 "kf_b3_p": "Godkjent WPS, sveisere sertifisert iht. EN ISO 9606-1 og en NDT-plan for hver jobb. Materialet kommer inn med 3.1-sertifikat; sveisekart og kontrollregistreringer knyttes til delens serienummer.",
 "kf_b4_h": "Hvordan følger jeg opp jobben min?",
 "kf_b4_p": "Ved ordrebekreftelse får dere en konto i kundeportalen: produksjonstrinn, estimert levering, dokumenter og forsendelse er synlige 24/7. Ingen grunn til å ringe og spørre.",
 "kf_l7": "Fabrikasjon av stålkonstruksjoner (EN 1090 EXC3)",
 "kf_l8": "Chassis- og bomfabrikasjon",
 "kf_l9": "Eksport til Europa: EN 1090 CE, engelsk dokumentasjon",
 "px_home_pages": "<span class=\"hf-lbl\">Tjenestesider</span><a href=\"celik-konstruksiyon.html\">Stålkonstruksjon</a><a href=\"sasi-bom-imalati.html\">Chassis- og bomfabrikasjon</a><a href=\"sac-kesim-bukum.html\">Platekutting og bøying</a><a href=\"tozalti-kaynak.html\">Pulverbuesveising</a><a href=\"avrupa-kaynakli-imalat.html\">Eksport til Europa</a>",
