 "cut_s1_desc": "Hvert trinn registreres under samme serienummer; én samlet dokumentasjon leveres, inkludert operasjoner utført hos partnere.",
 "cut_c1_icon": "Laser",
 "cut_c1_h": "Laserkutting",
 "cut_c1_p": "Tynne og middels tykke platedeler, presise konturer og hull; kutteplan direkte fra DXF, fugeforberedelse inkludert.",
