 "cut_c2_h": "Plasma- og brennskjæring",
 "cut_c2_p": "CNC-plasma- og brennskjæring for tykke plater og konstruksjonsdeler; toleransesatt kutting og forberedelse av sveisekanter.",
 "cut_c3_icon": "Bøying",
 "cut_c3_h": "CNC-kantpressebøying",
 "cut_c3_p": "V- og U-bøyer med programmerte vinkler og kompensasjon for tilbakefjæring; vinkel- og målkontroll ved mottak hos ArmaWeld.",
 "cut_c4_icon": "Valsing",
 "cut_c4_h": "Platevalsing",
 "cut_c4_p": "Valsing av tankskall, rør og koniske deler; langsgående sømmer sveises internt, lange sømmer på 35 m pulverbuelinjen.",
 "cut_c5_icon": "Sveising",
 "cut_c5_h": "Sveising og NDT",
 "cut_c5_p": "Kuttede og bøyde deler sveises internt etter godkjent WPS; VT, PT, MT og UT utføres av personell med ISO 9712 nivå 2.",
 "cut_c6_icon": "Montering",
 "cut_c6_h": "Maskinering, maling og montering",
 "cut_c6_p": "Maskinering og maling etter sveising i partnernettverket; mekanisk montering, momentregistrering og emballering klar for byggeplass internt.",
 "cut_s2_label": "Omfang",
 "cut_s2_title": "Hva gjøres hvor?",
 "cut_s2_desc": "Kritisk arbeid utføres internt; resten hos partnerbedrifter vi velger og reviderer, etter vår egen spesifikasjon. ArmaWeld står ansvarlig for den samlede kvaliteten.",
 "cut_r1k": "Internt",
 "cut_r1v": "Engineering, kutteplan, mottakskontroll, sveising, NDT, montering, dokumentasjon",
 "cut_r2k": "Partnernettverk (etter ArmaWelds spesifikasjon)",
 "cut_r2v": "Laser- og plasmakutting, kantpressebøying, valsing, maskinering, sandblåsing og maling",
 "cut_r3k": "Filformater",
 "cut_r3v": "DXF · DWG · STEP · PDF",
 "cut_r4k": "Materialer",
 "cut_r5k": "Materialsertifikat",
 "cut_r5v": "EN 10204 3.1 · smeltenummer koblet til delelisten",
 "cut_r6k": "Tilbud",
 "cut_r6v": "48 timer · én pris, én leveringstid · NDA som standard",
 "cut_s3_label": "Prosess",
 "cut_s3_title": "Slik jobber vi",
 "cut_st1_h": "Tegning og kutteplan",
 "cut_st1_p": "Deres DXF/STEP-fil gjennomgås for produserbarhet; kutteplan, bøyerekkefølge og fugeforberedelse utarbeides av ArmaWeld.",
 "cut_st2_h": "Materiale og kutting",
 "cut_st2_p": "Plater anskaffes med 3.1-sertifikat; laser- eller plasmakutting utføres hos en partnerbedrift etter ArmaWelds kutteplan.",
 "cut_st3_h": "Bøying og mottakskontroll",
 "cut_st3_p": "Bøyde deler ankommer ArmaWeld; vinkel, mål og overflate kontrolleres, og avvikende deler kommer aldri til sveising.",
 "cut_st4_h": "Sveising, kontroll og levering",
 "cut_st4_p": "Sveising etter godkjent WPS, NDT og målrapport; maling og montering ved behov. Delen leveres monteringsklar med tilhørende dokumentasjon.",
 "cut_s4_label": "Typiske deler",
 "cut_s4_title": "Hvilke deler passer dette for?",
 "cut_s4_desc": "For alle deler som skal sveises etter kutting og bøying; ordrer med kun kutting eller kun bøying kan også prises.",
 "cut_sec1_h": "Braketter og konsoller",
 "cut_sec1_p": "Bøyde braketter, forbindelsesplater",
 "cut_sec2_h": "Skap og innkapslinger",
 "cut_sec2_p": "Plateskap, deksler, vern",
 "cut_sec3_h": "Kassebjelker og profiler",
 "cut_sec3_p": "Bøyde kasseprofiler, U- og C-profiler",
 "cut_sec4_h": "Tanker og siloer",
 "cut_sec4_p": "Valsede skall, koniske siloer",
 "cut_sec5_h": "Maskindeler",
 "cut_sec5_p": "Rammeelementer, støtter, fiksturer",
 "cut_sec6_h": "Platedeler i serie",
 "cut_sec6_p": "Repeterbare serier, med serienummer",
 "cut_s5_label": "Ofte stilte spørsmål",
 "cut_s5_title": "FAQ om kutting og bøying",
 "cut_f1_q": "Utføres laserkutting og bøying hos ArmaWeld selv?",
 "cut_f1_a": "Kutting og bøying utføres hos partnerbedrifter som ArmaWeld velger og reviderer, etter vår egen spesifikasjon; kutteplan, materialanskaffelse og mottakskontroll er ArmaWelds ansvar. Sveising, NDT og montering gjøres internt, og ArmaWeld står ansvarlig for kvaliteten i hele kjeden.",
 "cut_f2_q": "Kan jeg bestille kun kutting eller kun bøying?",
 "cut_f2_a": "Ja, det kan prises. Den egentlige fordelen er imidlertid å planlegge kutting, bøying og sveising i én ordre: én pris, én leveringstid og deler klare til montering.",
 "cut_f3_q": "Hvilke filformater aksepterer dere?",
 "cut_f3_a": "DXF, DWG, STEP og PDF. For deler uten tegning måler vi opp prøvedelen og utarbeider verkstedtegningen.",
 "cut_f4_q": "Hvordan kontrolleres bøyetoleransene?",
 "cut_f4_a": "Hver bøyd del kontrolleres for vinkel og mål i ArmaWelds mottakskontroll; måleverdier tatt med kalibrerte instrumenter registreres under serienummeret. Avvikende deler sveises ikke.",
 "cut_f5_q": "Hva trenger dere for å gi et tilbud?",
 "cut_f5_a": "Teknisk tegning (DXF/DWG/STEP/PDF), stålkvalitet og tykkelse, antall, ønsket overflatebehandling og eventuelt kvalitetsklasse og NDT-krav. Tilbud innen 48 timer.",
 "cut_s6_title": "Relaterte sider",
 "cut_l_steel": "Fabrikasjon av stålkonstruksjoner",
 "cut_l_chassis": "Chassis- og bomfabrikasjon",
 "cut_l_blog1": "Veiledning for laser- og plasmakutting",
 "cut_l_blog2": "Bøyetoleranser for plater",
 "cut_cta_h": "Send oss deres DXF, motta monteringsklare deler",
 "cut_cta_p": "Kutting, bøying, sveising og kontroll under én kontrakt; tilbud med én pris og én leveringstid innen 48 timer.",
 "cut_ld_name": "Platekutting, bøying og sveising",
 "cut_ld_desc": "Laser- og plasmakutting, CNC-kantpressebøying, sveising, NDT og montering i én ordre fra Konya, Tyrkia. Kutteplan og mottakskontroll hos ArmaWeld; delene leveres klare til montering.",
 "cut_ld_type": "Platebearbeiding og sveiset fabrikasjon",
 "chb_title": "Chassis- og bomfabrikasjon | Tilhenger-, kran- og maskinrammer, Tyrkia — ArmaWeld",
 "chb_meta_desc": "Chassismoduler for tilhengere og lavlastere, kran- og gravemaskinbommer, rammer til landbrukshengere og maskiner. Godkjent WPS for S690QL, S960QL, Strenx og HARDOX; 35 m pulverbuelinje. Leveres klare for linjen. Be om tilbud.",
 "chb_og_title": "Chassis- og bomfabrikasjon | ArmaWeld, Tyrkia",
 "chb_breadcrumb": "Chassis og bommer",
 "chb_label": "Høyfast stål · pulverbuesveising · linjeklare moduler",
 "chb_h1": "Chassis- og bom<span>fabrikasjon</span><br>Tilhengere, kraner, maskiner",
 "chb_lead": "Hovedchassismoduler for lavlastere og tilhengere, bommer til mobilkraner og gravemaskiner, rammer til landbrukshengere og maskiner; sveist etter godkjent WPS fra S690QL til HARDOX, lange sømmer på vår 35 m pulverbuelinje, levert klare for monteringslinjen deres.",
 "chb_trust1": "S690QL · S960QL · Strenx",
 "chb_trust2": "35 m pulverbuelinje",
 "chb_trust3": "EN 1090 EXC3 · ISO 3834-2",
 "chb_trust4": "Leveres linjeklare",
 "chb_cta_saw": "Pulverbuelinje",
 "chb_s1_label": "Produktgrupper",
 "chb_s1_title": "Hvilke chassis og bommer bygger vi?",
 "chb_s1_desc": "Fra deres tegning, deres prøvedel eller ved reverse engineering. Fra enkeltprototype til serier; hver modul spores med serienummer.",
 "chb_c1_icon": "Tilhenger",
 "chb_c1_h": "Chassismoduler for tilhengere og lavlastere",
 "chb_c1_p": "Hovedchassis, langsgående bjelker og tverrbjelker; godkjent WPS i S690QL og S960QL, med retthet og målrepeterbarhet over lange lengder.",
 "chb_c2_icon": "Kran",
 "chb_c2_h": "Bommer og chassis til mobilkraner",
 "chb_c2_p": "Kasseprofiler til teleskopbommer, kranbjelker og støttebeinsenheter; kontrollert sveiserekkefølge og deformasjonsovervåking for utmattingslast.",
 "chb_c3_icon": "Gravemaskin",
 "chb_c3_h": "Bommer, stikker og frontrammer til gravemaskiner",
 "chb_c3_p": "Bommer og stikker, skuffer og hurtigfester, frontrammer og motvektsrammer; bufferlag og lavhydrogen-tilsettmaterialer for HARDOX og Strenx.",
 "chb_c4_icon": "Landbruk",
 "chb_c4_h": "Rammer til landbrukshengere og maskiner",
 "chb_c4_p": "Tilhengerchassis, bærebjelker til skurtreskere og landbruksmaskiner; repeterbar kvalitet i serier.",
