 "chb_c5_h": "Maskinrammer og hovedkropper",
 "chb_c5_p": "Rammer, hovedkropper, chassis og fundamenter for maskin- og utstyrsprodusenter; sveiste konstruksjoner klare for maskinering og montering.",
 "chb_c6_icon": "Påbygg",
