 "chb_r3v": "Forvarming iht. EN 1011-2 · H5-tilsettmaterialer · registrering av mellomstrengtemperatur · varmetilførsel ≤ 1,5 kJ/mm på S700MC",
 "chb_r4k": "Kvalitetssystem",
 "chb_r4v": "EN ISO 3834-2 · EN 1090 EXC3 · EN ISO 5817 B · sveisere iht. EN ISO 9606-1",
