 "chb_s3_label": "Prosess",
 "chb_s3_title": "Slik jobber vi",
 "chb_st1_h": "Teknisk gjennomgang",
 "chb_st1_p": "Deres DWG-, DXF-, STEP- eller PDF-tegning gjennomgås for produserbarhet, sveisedetaljer og fiksturering; materiale og WPS velges. Tilbud innen 48 timer.",
 "chb_st2_h": "Prøve og førstegangsgodkjenning",
 "chb_st2_p": "Den første modulen legges frem for deres godkjenning med målrapport og NDT; serieproduksjonen starter etter godkjenning.",
 "chb_st3_h": "Sveising i fiksturer",
 "chb_st3_p": "Lange langsgående sømmer sveises i én oppspenning på 35 m pulverbuelinjen; kilsveiser og posisjonssveiser med MAG/FCAW. Strøm, spenning og hastighet registreres for hver sveis.",
 "chb_st4_h": "Kontroll, maling og utsendelse",
 "chb_st4_p": "NDT og målkontroll internt; sandblåsing og maling hos en partnerbedrift etter ArmaWelds spesifikasjon. Materialsertifikater, WPS, NDT- og målrapporter i leveransedokumentasjonen.",
 "chb_s4_label": "Bransjer",
 "chb_s4_title": "Hvem bygger vi for?",
 "chb_s4_desc": "Produsenter med egen monteringslinje som vil kjøpe den sveiste modulen eksternt:",
 "chb_sec1_h": "Tilhenger- og semitrailerprodusenter",
