 "pg_belgelerimiz_title": "Sertifikater — ArmaWeld",
 "pg_belgelerimiz_desc": "ArmaWelds offisielle sertifikater: se og last ned EN 1090-2 EXC3, EN ISO 3834-2, ISO 9001:2015, ISO 14001:2015 og ISO 45001:2018.",
 "pg_hakkimizda_title": "Om oss | Sveisebedrift i Konya, Tyrkia — ArmaWeld",
 "pg_hakkimizda_desc": "ArmaWeld-teamet: sveiseingeniører, NDT-teknikere og sertifiserte sveisere som jobber som ett tverrfaglig team.",
 "pg_hizmetler_title": "Sveisetjenester | MIG/MAG, TIG, SAW, laserkutting, bøying — ArmaWeld",
 "pg_hizmetler_desc": "Våre tjenester innen sveiset fabrikasjon: MIG/MAG- og TIG-sveising, 35 m pulverbuesveising, laserkutting, CNC-bøying, mekanisk montering og NDT. Sertifisert etter EN 1090-2, ISO 3834-2, ISO 9001, 14001, 45001.",
 "pg_iletisim_title": "Kontakt og tilbud | Sveiset fabrikasjon i Konya, Tyrkia — ArmaWeld",
 "pg_iletisim_desc": "Del de tekniske detaljene og få svar innen 48 timer. Hurtig tilbudsskjema for materiale, tykkelse og bruksområde.",
 "pg_index_title": "Sveisebedrift i Konya, Tyrkia | EN 1090 — ArmaWeld",
 "pg_index_desc": "Sveiset fabrikasjon, sveising på kontrakt og NDT i Konya, Tyrkia, med eksport til Europa. MIG/MAG, TIG, 35 m pulverbuesveising, laserkutting, CNC-bøying. Sertifisert etter EN 1090-2 EXC3 CE og EN ISO 3834-2; EXW/DAP-levering.",
 "pg_kalite_title": "Kvalitet og sporbarhet | EN ISO 3834-2, WPS og NDT-rapporter — ArmaWeld",
 "pg_kalite_desc": "Produksjon sertifisert etter EN 1090-2 EXC3, EN ISO 3834-2, ISO 9001:2015, ISO 14001:2015, ISO 45001:2018, EN ISO 15614-1/2 og EN ISO 9606-1/2, med full sporbarhet.",
 "pg_kaynak_title": "MIG/MAG- og TIG-sveisetjenester | Profesjonell sveiset fabrikasjon — ArmaWeld",
 "pg_kaynak_desc": "MIG/MAG- og TIG-sveisetjenester: EN ISO 3834-2-sertifisert industriproduksjon med kvalifiserte sveisere, prosjektbasert eller i serie. Be om tilbud.",
 "pg_ndt_title": "NDT-tjenester i Konya, Tyrkia | VT, PT, MT, UT — ArmaWeld",
 "pg_ndt_desc": "Ikke-destruktiv testing med VT, PT, MT, UT og RT, utført av personell sertifisert etter EN ISO 9712 nivå 2.",
 "pg_projeler_title": "Prosjekter | Sveiset fabrikasjon og stålkonstruksjon — ArmaWeld",
 "pg_projeler_desc": "Utvalgte referanseprosjekter innen anleggsmaskiner, stålkonstruksjon, energi, jernbane og prosessutstyr, med materiale, sveisemetode og NDT-omfang.",
 "pg_sektorler_title": "Bransjer: Maskiner, stålkonstruksjon, trykkbeholdere, energi | ArmaWeld",
 "pg_sektorler_desc": "Sveiset fabrikasjon for anleggsmaskiner, transport og logistikk, energiinfrastruktur og industrianlegg. S700MC, HARDOX, P355GH og mer.",
 "pg_sss_title": "FAQ | Sveising på kontrakt og sveiset fabrikasjon — ArmaWeld",
 "pg_sss_desc": "Ofte stilte spørsmål og tekniske svar om sveisestandarder, stålgrupper, sertifikatomfang og produksjonsprosesser.",
