 "px_hz_14": "■ PULVERBUESVEISING · SAW",
 "px_hz_15": "KONTRAKT · MIG/MAG- OG TIG-SVEISING · PROSJEKTBASERT PRODUKSJON",
 "px_hz_16": "Sveiset fabrikasjon på kontrakt.<br/><span>Prosjektbaserte industriløsninger.</span>",
 "px_hz_18": "Fra deres tegning til levering: sveiset fabrikasjon på kontrakt og prosjektbasert produksjon. MIG/MAG- og TIG-sveising, sertifisert etter EN 1090 og ISO 3834-2, med ingeniøroptimalisert kostnad og sertifisert kvalitet.",
 "px_hz_19": "Sertifisert produksjonsoppsett",
 "px_hz_20": "Med EN ISO 3834-2 kvalitetsstyring for sveising og EN 1090 EXC3-sertifisering produseres hver del med sporbare registreringer.",
 "px_hz_21": "MIG/MAG- og TIG-sveising",
 "px_hz_22": "MIG/MAG- og TIG-fabrikasjon med godkjente WPS i karbonstål, rustfritt stål, aluminium og høyfast stål.",
 "px_hz_23": "Prosjektbasert fleksibilitet",
 "px_hz_24": "Vi planlegger produksjon fra enkeltprototyper til serier i mellomstort volum. Det er ingen minimumsbestilling.",
 "px_hz_25": "Optimalisert kostnad og transparente tilbud",
 "px_hz_26": "Ingeniørdisiplin øker den operative effektiviteten; unødvendige kostnader fjernes, og dere mottar et transparent og konkurransedyktig tilbud.",
 "px_hz_27": "Fullt integrert prosess",
 "px_hz_28": "Sveising, NDT og maling internt; platekutting og bøying koordineres innenfor prosjektplanen. Ett kontaktpunkt og sporbar levering.",
 "px_hz_29": "Ingeniøroppfølging",
 "px_hz_30": "Hvert kontraktprosjekt får en kvalitetsplan under en IWE/IWT-sertifisert ingeniør, og sveiseparametrene registreres.",
 "px_hz_31": "Produksjonsprosess: Fra tegning til levering",
 "px_hz_32": "Teknisk gjennomgang og tilbud",
 "px_hz_33": "Vi gjennomgår tegningen eller prøven, definerer materialgruppe, sveisemetode (MIG/MAG eller TIG), toleranser og dokumentasjon, og utarbeider deretter tilbudet.",
 "px_hz_34": "WPS-valg og produksjonsplan",
 "px_hz_35": "En godkjent sveiseprosedyre (WPS/WPQR) velges, og det utarbeides en produksjonsplan med sveiserekkefølge og kontrollpunkter.",
 "px_hz_36": "Sveising og NDT",
 "px_hz_37": "Kvalifiserte sveisere utfører MIG/MAG- eller TIG-sveising, og nødvendig NDT (UT, MT, PT, VT) gjennomføres.",
 "px_hz_38": "Når dimensjonskontroll, visuell kontroll og kvalitetsregistreringer er fullført, sendes delene sammen med produksjonsdokumentasjonen.",
 "px_hz_39": "Hvilken sveisemetode passer for deres prosjekt?",
 "px_hz_40": "MIG/MAG-sveising",
 "px_hz_41": "TIG-sveising",
 "px_hz_42": "Bruksområde",
 "px_hz_43": "Konstruksjonsstål, kontraktarbeid i serie",
 "px_hz_44": "Rustfritt, aluminium, presisjonsdeler",
 "px_hz_45": "Høy",
 "px_hz_46": "— egnet for serieproduksjon",
 "px_hz_47": "Middels — presis, langsommere",
 "px_hz_48": "Sveisekvalitet",
 "px_hz_49": "God — konstruksjon",
 "px_hz_50": "Svært god",
 "px_hz_51": "— synlige og fine sømmer",
 "px_hz_52": "Karbonstål, høyfast",
 "px_hz_53": "Rustfritt, aluminium, legeringer",
 "px_hz_54": "Høy (robotkompatibel)",
 "px_hz_55": "Middels",
 "px_hz_56": "Ofte stilte spørsmål",
 "px_hz_57": "Hva er sveiset fabrikasjon på kontrakt?",
 "px_hz_58": "Det er leieproduksjon der sveisebedriften bygger deler etter kundens tegninger eller prøver med eget utstyr og kvalifiserte sveisere. ArmaWeld leverer dette med godkjente WPS i henhold til EN 1090 og ISO 3834-2.",
 "px_hz_59": "Er det et minimum bestillingsantall for prosjektbasert fabrikasjon?",
 "px_hz_60": "ArmaWeld håndterer både enkeltprototyper og serieproduksjon. Det er ikke noe minimum bestillingsantall (MOQ); produksjonsplanen følger prosjektets krav.",
 "px_hz_61": "Hva er forskjellen mellom MIG/MAG- og TIG-sveising?",
 "px_hz_62": "MIG/MAG (ISO 4063: 135/136) er ideell for produktivt seriearbeid og foretrekkes for konstruksjonsstål. TIG (ISO 4063: 141) gir overlegen kvalitet på rustfritt stål, aluminium og tynnveggede presisjonsdeler. ArmaWeld bruker begge med godkjente WPS og kvalifiserte sveisere.",
 "px_hz_63": "Hvilke dokumenter leverer dere for sveising på kontrakt?",
 "px_hz_64": "EN ISO 3834-2 sveisekvalitetssertifikat, EN 1090 EXC3-sertifikat for utførelsesklasse, godkjente WPS/WPQR, sveisesertifikater og, på forespørsel, NDT-rapporter (UT, MT, PT).",
 "px_hz_65": "Hvilke bransjer betjener dere?",
 "px_hz_66": "Vi leverer sveiset fabrikasjon på kontrakt og prosjektbaserte løsninger til produsenter innen maskiner, bygg og stålkonstruksjoner, landbruksmaskiner, forsvar, energi, hydraulikk og spesialutstyr for industrien.",
 "px_hz_67": "(200 mm, prosjektbasert)",
