 "pt_s_teklif_list": "<ul><li>Ny forespørsel ved å laste opp DWG / DXF / PDF</li><li>Forespørselsstatus: venter, tilbud gitt, omgjort til ordre, avslått</li><li>Forespørselshistorikk med innsendings- og måldatoer</li></ul>",
